Append('<!DOCTYPE html>')
Append('<html lang="ar" dir="rtl">')
Append('<head>')
Append('<meta charset="UTF-8"/>')
Append('<meta name="viewport" content="width=device-width, initial-scale=1.0"/>')
Append('<title>مطور مواقع احترافي</title>')
Append('<link rel="preconnect" href="https://fonts.googleapis.com"/>')
Append('<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet"/>')
Append('<style>')
Append('*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}')
Append('html{scroll-behavior:smooth}')
Append('body{font-family:Cairo,sans-serif;direction:rtl;color:#1a2340;background:#fff;line-height:1.7;overflow-x:hidden}')
Append('a{text-decoration:none;color:inherit}ul{list-style:none}img{max-width:100%;display:block}')
Append(':root{--navy:#1a2340;--blue:#2563eb;--blue-light:#3b82f6;--blue-soft:#eff6ff;--pink-soft:#fdf2f8;--mint-soft:#f0fdf4;--gray-soft:#f8fafc;--gray-200:#e2e8f0;--gray-400:#94a3b8;--gray-600:#64748b;--radius-sm:10px;--radius-md:16px;--radius-lg:24px;--radius-xl:32px;--shadow-sm:0 2px 12px rgba(0,0,0,.06);--shadow-md:0 8px 30px rgba(0,0,0,.10);--shadow-lg:0 16px 48px rgba(0,0,0,.12)}')
Append('.container{max-width:1180px;margin:0 auto;padding:0 24px}')
Append('.section-label{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--blue);background:var(--blue-soft);border-radius:100px;padding:4px 14px;margin-bottom:16px}')
