Append('.btn{display:inline-flex;align-items:center;gap:8px;font-family:Cairo,sans-serif;font-weight:700;font-size:15px;border-radius:100px;padding:13px 28px;cursor:pointer;transition:all .25s;border:none}')
Append('.btn-primary{background:var(--blue);color:#fff}.btn-primary:hover{background:#1d4ed8;transform:translateY(-2px);box-shadow:0 8px 24px rgba(37,99,235,.35)}')
Append('.btn-outline{background:transparent;color:var(--navy);border:2px solid var(--gray-200)}.btn-outline:hover{border-color:var(--blue);color:var(--blue)}')
Append('.btn-white{background:#fff;color:var(--blue);font-weight:700}.btn-white:hover{background:#f0f7ff;transform:translateY(-2px)}')
Append('/* NAV */header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.96);backdrop-filter:blur(12px);border-bottom:1px solid var(--gray-200)}')
Append('.nav{display:flex;align-items:center;justify-content:space-between;height:68px}')
Append('.nav-logo{display:flex;flex-direction:column;line-height:1.2}')
Append('.logo-name{font-size:18px;font-weight:800;color:var(--navy)}.logo-sub{font-size:11px;color:var(--gray-400);font-weight:500}')
Append('.nav-links{display:flex;align-items:center;gap:32px}.nav-links a{font-size:14px;font-weight:600;color:var(--gray-600);transition:color .2s}.nav-links a:hover{color:var(--blue)}')
Append('.nav-actions{display:flex;align-items:center;gap:12px}')
Append('.nav-badge{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:#16a34a;background:#f0fdf4;border-radius:100px;padding:6px 14px}')
