Append('.hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:4px}.hamburger span{display:block;width:24px;height:2px;background:var(--navy);border-radius:2px;transition:all .3s}')
Append('/* HERO */.hero{padding:80px 0 60px;background:#fff;position:relative;overflow:hidden}')
