Append('.hero::after{content:"";position:absolute;bottom:-80px;right:-120px;width:380px;height:380px;border-radius:50%;background:radial-gradient(circle,rgba(139,92,246,.06) 0%,transparent 70%);pointer-events:none}')
Append('.hero-inner{display:flex;align-items:center;gap:48px}.hero-text{flex:1}')
Append('.hero-tag{display:inline-flex;align-items:center;gap:8px;background:var(--blue-soft);color:var(--blue);border-radius:100px;padding:6px 16px;font-size:13px;font-weight:700;margin-bottom:20px}')
