Append('.badge-icon{width:36px;height:36px;border-radius:10px;background:var(--blue-soft);display:flex;align-items:center;justify-content:center;font-size:18px}')
Append('/* PROJECTS */.projects{padding:80px 0}.projects-header{text-align:center;margin-bottom:60px}')
