Append('/* SERVICES */.services{padding:80px 0;background:var(--gray-soft)}.services-header{text-align:center;margin-bottom:48px}')
Append('.services-header h2{font-size:clamp(26px,4vw,40px);font-weight:900;color:var(--navy)}.services-header p{font-size:16px;color:var(--gray-600);margin-top:10px}')
Append('.services-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}')
Append('.service-card{background:#fff;border-radius:var(--radius-lg);padding:32px 28px;box-shadow:var(--shadow-sm);border:1px solid var(--gray-200);transition:all .3s;position:relative;overflow:hidden}')
Append('.service-card:hover{box-shadow:var(--shadow-md);transform:translateY(-4px);border-color:rgba(37,99,235,.2)}')
Append('.service-num{font-size:48px;font-weight:900;color:rgba(37,99,235,.08);position:absolute;top:16px;left:20px;line-height:1}')
Append('.service-icon{width:52px;height:52px;border-radius:14px;background:var(--blue-soft);display:flex;align-items:center;justify-content:center;font-size:24px;margin-bottom:18px}')
Append('.service-card h3{font-size:18px;font-weight:800;color:var(--navy);margin-bottom:10px}')
Append('.service-card p{font-size:14px;color:var(--gray-600);line-height:1.7}')
Append('/* PROCESS */.process{padding:80px 0}.process-header{text-align:center;margin-bottom:56px}')
Append('.process-header h2{font-size:clamp(26px,4vw,40px);font-weight:900;color:var(--navy)}.process-header p{font-size:16px;color:var(--gray-600);margin-top:10px}')
