Append('.process-grid::before{content:"";position:absolute;top:38px;right:10%;left:10%;height:2px;background:linear-gradient(90deg,var(--blue) 0%,var(--gray-200) 100%);z-index:0}')
Append('.process-step{text-align:center;padding:0 16px;position:relative;z-index:1}')
