Append('.process-step h3{font-size:16px;font-weight:800;color:var(--navy);margin-bottom:8px}.process-step p{font-size:13px;color:var(--gray-600);line-height:1.6}')
Append('/* CONTACT */.contact{padding:80px 0;background:var(--gray-soft)}.contact-inner{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:start}')
Append('.contact-info h2{font-size:clamp(26px,4vw,38px);font-weight:900;color:var(--navy);margin-bottom:16px;line-height:1.3}')
Append('.contact-info h2 .accent{color:var(--blue)}.contact-info p{font-size:15px;color:var(--gray-600);margin-bottom:32px}')
