Append('.contact-detail .icon{width:44px;height:44px;border-radius:12px;background:var(--blue-soft);display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0}')
Append('.contact-detail .text strong{display:block;font-size:14px;font-weight:700;color:var(--navy)}.contact-detail .text span{font-size:13px;color:var(--gray-600)}')
Append('.social-row{display:flex;gap:12px;margin-top:24px}')
Append('.social-btn{width:42px;height:42px;border-radius:12px;background:#fff;border:1px solid var(--gray-200);display:flex;align-items:center;justify-content:center;font-size:16px;transition:all .2s;cursor:pointer;text-decoration:none}')
Append('.social-btn:hover{border-color:var(--blue);background:var(--blue-soft)}')
Append('.contact-form{background:#fff;border-radius:var(--radius-xl);padding:40px 36px;box-shadow:var(--shadow-md);border:1px solid var(--gray-200)}')
Append('.contact-form h3{font-size:20px;font-weight:800;color:var(--navy);margin-bottom:24px}')
Append('.form-group{margin-bottom:18px}.form-group label{display:block;font-size:13px;font-weight:700;color:var(--navy);margin-bottom:8px}')
Append('.form-group input,.form-group textarea,.form-group select{width:100%;border:1.5px solid var(--gray-200);border-radius:var(--radius-sm);padding:12px 16px;font-family:Cairo,sans-serif;font-size:14px;color:var(--navy);background:#fafafa;transition:border-color .2s,box-shadow .2s;outline:none;direction:rtl}')
