Append('.form-group textarea{resize:vertical;min-height:120px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}')
Append('/* FAQ */.faq{padding:80px 0}.faq-inner{display:grid;grid-template-columns:1fr 1.6fr;gap:60px;align-items:start}')
Append('.faq-left h2{font-size:clamp(24px,3.5vw,36px);font-weight:900;color:var(--navy);line-height:1.35;margin-bottom:16px}')
Append('.faq-left h2 .accent{color:var(--blue)}.faq-left p{font-size:15px;color:var(--gray-600);margin-bottom:28px}')
Append('.faq-list{display:flex;flex-direction:column;gap:12px}')
Append('.faq-item{background:#fff;border:1px solid var(--gray-200);border-radius:var(--radius-md);overflow:hidden;box-shadow:var(--shadow-sm);transition:box-shadow .2s}')
