Append('/* CTA */.cta-strip{background:var(--navy);padding:80px 0;text-align:center;position:relative;overflow:hidden}')
Append('.cta-strip::before{content:"";position:absolute;top:-100px;left:50%;transform:translateX(-50%);width:600px;height:400px;border-radius:50%;background:radial-gradient(circle,rgba(37,99,235,.25) 0%,transparent 70%)}')
Append('.cta-strip h2{font-size:clamp(28px,4vw,46px);font-weight:900;color:#fff;margin-bottom:16px;position:relative}')
Append('.cta-strip h2 .accent{color:var(--blue-light)}.cta-strip p{font-size:16px;color:rgba(255,255,255,.65);margin-bottom:36px;position:relative}')
