Append('/* FOOTER */footer{background:#0f172a;color:rgba(255,255,255,.7);padding:56px 0 32px}')
Append('.footer-inner{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:40px;margin-bottom:48px}')
Append('.footer-brand .logo-name{font-size:22px;font-weight:900;color:#fff;margin-bottom:10px}.footer-brand p{font-size:13px;line-height:1.7;margin-bottom:20px}')
Append('.footer-social{display:flex;gap:10px}')
