Append('.footer-col h4{font-size:14px;font-weight:800;color:#fff;margin-bottom:16px}')
Append('.footer-col ul{display:flex;flex-direction:column;gap:10px}.footer-col ul li a{font-size:13px;color:rgba(255,255,255,.6);transition:color .2s}.footer-col ul li a:hover{color:#fff}')
Append('.footer-bottom{border-top:1px solid rgba(255,255,255,.08);padding-top:24px;display:flex;justify-content:space-between;align-items:center;font-size:13px;flex-wrap:wrap;gap:12px}')
Append('.copy{color:rgba(255,255,255,.45)}.footer-links{display:flex;gap:20px}.footer-links a{color:rgba(255,255,255,.45);transition:color .2s}.footer-links a:hover{color:#fff}')
Append('/* RESPONSIVE */@media(max-width:1024px){.hero-inner{flex-direction:column}.hero-visual{flex:unset;width:100%;max-width:580px;margin:0 auto}.footer-inner{grid-template-columns:1fr 1fr}.project-block{grid-template-columns:1fr}.project-block.reverse{direction:rtl}.project-img-wrap{order:-1}.process-grid::before{display:none}.services-grid{grid-template-columns:repeat(2,1fr)}}')
Append('@media(max-width:768px){.nav-links{display:none}.nav-badge{display:none}.hamburger{display:flex}.nav-links.open{display:flex;flex-direction:column;gap:0;position:absolute;top:68px;right:0;left:0;background:#fff;border-bottom:1px solid var(--gray-200);padding:12px 0;z-index:99;box-shadow:var(--shadow-md)}.nav-links.open a{padding:13px 24px;width:100%;border-bottom:1px solid var(--gray-200)}header{position:relative}.hero{padding:48px 0 40px}.hero-stats{gap:20px}.hero-cta{gap:10px}.btn{font-size:14px;padding:11px 22px}.contact-inner{grid-template-columns:1fr;gap:32px}.faq-inner{grid-template-columns:1fr;gap:32px}.form-row{grid-template-columns:1fr}.footer-inner{grid-template-columns:1fr 1fr;gap:28px}.footer-bottom{flex-direction:column;gap:12px;text-align:center}.process-grid{grid-template-columns:1fr 1fr;gap:32px}.services-grid{grid-template-columns:1fr 1fr}}')
Append('@media(max-width:480px){.hero h1{font-size:30px}.footer-inner{grid-template-columns:1fr}.project-info{padding:28px 22px}.project-img-wrap{padding:20px}.project-info h3{font-size:20px}.contact-form{padding:28px 20px}.services-grid{grid-template-columns:1fr}.process-grid{grid-template-columns:1fr}}')
Append('</style></head><body>')

